<script setup>defineProps({modelValue:String,items:{default:()=>[]}});defineEmits(['update:modelValue'])</script><template><div class="tabs" role="tablist"><button v-for="i in items" :key="i.value" role="tab" :aria-selected="modelValue===i.value" :class="{on:modelValue===i.value}" @click="$emit('update:modelValue',i.value)">{{i.label}}</button></div></template><style scoped>.tabs{display:flex;border-bottom:1px solid var(--border-subtle)}button{position:relative;min-height:44px;padding:0 14px;border:0;background:transparent;color:var(--text-muted);font:600 14px var(--font-core)}button.on{color:var(--text-primary)}button.on:after{position:absolute;right:10px;bottom:-1px;left:10px;height:2px;border-radius:2px;background:var(--action-primary);content:''}</style>
